# Derives the S01 sounds from recordings already in the project (Kenney CC0) and from
# synthesised noise. Nothing here is generated by an AI model: it is ordinary signal processing.
#
#   powershell -File Tools/build_audio.ps1
#
#   tell_1..3     an attack's wind-up tell: a swing recording reversed (a rising "suck-in"),
#                 lowered and softened, so a coming blow is heard before it lands
#   ambience_meadow_1   a 24 s seamless wind bed for the meadow floors: brown noise, band-limited,
#                 with a slow swell; looped quietly under the score and ducked in fights
param([string]$Ffmpeg = "$env:USERPROFILE\.cache\ffmpeg-dl\ffmpeg-9.0.2-essentials_build\bin\ffmpeg.exe")
$ErrorActionPreference = 'Stop'
$audio = Join-Path (Split-Path $PSScriptRoot -Parent) 'Assets\Resources\Audio'
if (-not (Test-Path $Ffmpeg)) { throw "ffmpeg not found at $Ffmpeg" }

$sources = @('swing_1', 'swing_3', 'swing_5')
for ($i = 0; $i -lt $sources.Count; $i++) {
    $in = Join-Path $audio ($sources[$i] + '.ogg')
    $out = Join-Path $audio ('tell_' + ($i + 1) + '.ogg')
    # Reverse, drop about four semitones, keep it below the hit's brightness, fade in from nothing.
    & $Ffmpeg -y -loglevel error -i $in -af "areverse,asetrate=44100*0.78,aresample=44100,lowpass=f=2600,highpass=f=90,afade=t=in:d=0.12,loudnorm=I=-18:TP=-3:LRA=7" -c:a libvorbis -q:a 5 $out
    if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for $out" }
}

# Wind: brown noise, band-limited, with a slow swell. The last two seconds cross-fade into the
# first two so it loops without a seam.
$wind = Join-Path $audio 'ambience_meadow_1.ogg'
$tmp = Join-Path $env:TEMP 'greyspire_wind_raw.wav'
& $Ffmpeg -y -loglevel error -f lavfi -i "anoisesrc=color=brown:amplitude=0.6:duration=26:seed=734912" -af "lowpass=f=900,highpass=f=70,tremolo=f=0.11:d=0.45,volume=0.9" -ar 44100 -ac 2 $tmp
if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for the wind source" }
& $Ffmpeg -y -loglevel error -i $tmp -filter_complex "[0:a]atrim=0:2,asetpts=PTS-STARTPTS[head];[0:a]atrim=2:26,asetpts=PTS-STARTPTS[body];[body][head]acrossfade=d=2:c1=tri:c2=tri" -c:a libvorbis -q:a 4 $wind
if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for $wind" }
Remove-Item $tmp
Get-ChildItem $audio -Filter 'tell_*.ogg' | ForEach-Object { 'built ' + $_.Name + ' ' + $_.Length }
Get-Item $wind | ForEach-Object { 'built ' + $_.Name + ' ' + $_.Length }
